//! pixel-art icons in the shaded windows 95 / nt4 style: 32 by 32 for the desktop and the
//! module windows, and hand-drawn 16 by 16 ones for title bars, the taskbar and menus. the art
//! lives in icon_data.rs, generated by tools/make-icons.py.

use eframe::egui::{Color32, Mesh, Painter, Pos2, Rect, Shape, Vec2};
use eframe::emath::GuiRounding as _;

use crate::icon_data as data;

/// one palette letter per pixel, the sixteen windows colours; `.` is transparent.
fn colour(c: char) -> Option<Color32> {
    Some(match c {
        'k' => Color32::BLACK,
        'w' => Color32::WHITE,
        'g' => Color32::from_rgb(192, 192, 192),
        'd' => Color32::from_rgb(128, 128, 128),
        'n' => Color32::from_rgb(0, 0, 128),
        'b' => Color32::from_rgb(0, 0, 255),
        'c' => Color32::from_rgb(0, 255, 255),
        't' => Color32::from_rgb(0, 128, 128),
        'G' => Color32::from_rgb(0, 128, 0),
        'l' => Color32::from_rgb(0, 255, 0),
        'y' => Color32::from_rgb(255, 255, 0),
        'o' => Color32::from_rgb(128, 128, 0),
        'r' => Color32::from_rgb(255, 0, 0),
        'm' => Color32::from_rgb(128, 0, 0),
        'p' => Color32::from_rgb(128, 0, 128),
        'f' => Color32::from_rgb(255, 0, 255),
        _ => return None,
    })
}

/// the 32 by 32 icon for a module id, or for the built-in windows ("console", "hosts",
/// "settings", "folder").
pub fn art(id: &str) -> &'static [&'static str] {
    match id {
        "gateway" => &data::GATEWAY,
        "docker" => &data::DOCKER,
        "nt4-domain" => &data::NT4,
        "web-proxy" => &data::WEB,
        "remote-commands" => &data::COMMANDS,
        "dns" => &data::DNS,
        "console" => &data::CONSOLE,
        "settings" => &data::SETTINGS,
        "folder" => &data::FOLDER,
        "my-server" => &data::MYSERVER,
        "networks" => &data::NETWORKS,
        _ => &data::HOSTS,
    }
}

/// the hand-drawn 16 by 16 icon for the same ids, plus "lanlord" for the menu button and "update" for the update notice.
pub fn small(id: &str) -> &'static [&'static str] {
    match id {
        "gateway" => &data::SMALL_GATEWAY,
        "docker" => &data::SMALL_DOCKER,
        "nt4-domain" => &data::SMALL_NT4,
        "web-proxy" => &data::SMALL_WEB,
        "remote-commands" => &data::SMALL_COMMANDS,
        "dns" => &data::SMALL_DNS,
        "console" => &data::SMALL_CONSOLE,
        "settings" => &data::SMALL_SETTINGS,
        "folder" => &data::SMALL_FOLDER,
        "my-server" => &data::SMALL_MYSERVER,
        "networks" => &data::SMALL_NETWORKS,
        "lanlord" => &data::SMALL_LANLORD,
        "update" => &data::SMALL_UPDATE,
        "datetime" => &SMALL_CLOCK,
        _ => &data::SMALL_HOSTS,
    }
}

/// how many frames the update icon in the tray has: one full turn of its globe.
#[cfg(feature = "native")]
pub const UPDATE_FRAMES: usize = data::SMALL_UPDATE_FRAMES.len();

/// frame `i` of the update icon, wrapping round; frame 0 is the still `small("update")`.
#[cfg(feature = "native")]
pub fn update_frame(i: usize) -> &'static [&'static str] {
    &data::SMALL_UPDATE_FRAMES[i % UPDATE_FRAMES]
}

/// how many frames the installing animation has: a progress strip that fills and wraps.
#[cfg(feature = "native")]
pub const INSTALL_FRAMES: usize = data::SMALL_UPDATE_INSTALL_FRAMES.len();

/// frame `i` of the installing animation, wrapping round.
#[cfg(feature = "native")]
pub fn install_frame(i: usize) -> &'static [&'static str] {
    &data::SMALL_UPDATE_INSTALL_FRAMES[i % INSTALL_FRAMES]
}

/// the globe with a pause badge, for an update that is paused.
#[cfg(feature = "native")]
pub fn update_paused() -> &'static [&'static str] {
    &data::SMALL_UPDATE_PAUSED
}

/// the grey globe with a red cross, for an update that failed.
#[cfg(feature = "native")]
pub fn update_failed() -> &'static [&'static str] {
    &data::SMALL_UPDATE_FAILED
}

/// the globe with a green check, for an update that is installed and waits for a restart.
#[cfg(feature = "native")]
pub fn update_done() -> &'static [&'static str] {
    &data::SMALL_UPDATE_DONE
}

/// the title bar icon of the Date/Time window, drawn by hand here (the generated icons are not
/// for a window that is opened from the taskbar rather than the desktop).
const SMALL_CLOCK: [&str; 16] = [
    "......kkkk......",
    "....kkkwwkkk....",
    "..kkwwwwwwwwkk..",
    "..kwwwwkwwwwdk..",
    ".kwwwwwkwwwwddk.",
    ".kwwwwwkwwwwwdk.",
    "kkwwwwwkwwwwwdkk",
    "kwwwwwwkwwwwwwdk",
    "kwwwwwwkkkwwwwdk",
    "kkwwwwwwwwkkwdkk",
    ".kwwwwwwwwwwwdk.",
    ".kwwwwwwwwwwddk.",
    "..kddwwwwwwddk..",
    "..kkdddwwdddkk..",
    "....kkkddkkk....",
    "......kkkk......",
];

/// draw `art` with its top-left corner at `pos`, each pixel `scale` points wide. the pixels go out
/// as one mesh of plain quads: filled rects this small would be feathered into thin lines, which
/// some screens render as nothing.
pub fn draw(painter: &Painter, pos: Pos2, art: &[&str], scale: f32) {
    let pos = pos.round_to_pixels(painter.pixels_per_point());
    let mut mesh = Mesh::default();
    for (y, row) in art.iter().enumerate() {
        for (x, c) in row.chars().enumerate() {
            if let Some(colour) = colour(c) {
                let min = pos + Vec2::new(x as f32, y as f32) * scale;
                mesh.add_colored_rect(Rect::from_min_size(min, Vec2::splat(scale)), colour);
            }
        }
    }
    painter.add(Shape::mesh(mesh));
}

#[cfg(test)]
mod tests {
    use super::*;

    const IDS: [&str; 12] = [
        "gateway",
        "docker",
        "nt4-domain",
        "web-proxy",
        "remote-commands",
        "dns",
        "console",
        "hosts",
        "settings",
        "folder",
        "my-server",
        "networks",
    ];

    #[test]
    fn the_update_icon_has_a_full_turn_of_frames_that_differ() {
        assert_eq!(UPDATE_FRAMES, 8);
        for i in 0..UPDATE_FRAMES {
            check("update frame", update_frame(i), 16);
        }
        assert_eq!(update_frame(0), small("update"), "the balloon uses frame 0");
        assert_eq!(update_frame(UPDATE_FRAMES), update_frame(0), "it wraps");
        // a spinning globe: no two frames of the turn are the same picture
        for a in 0..UPDATE_FRAMES {
            for b in (a + 1)..UPDATE_FRAMES {
                assert_ne!(update_frame(a), update_frame(b), "frames {a} and {b}");
            }
        }
    }

    #[test]
    fn every_state_of_the_tray_icon_has_art_in_the_palette() {
        assert_eq!(INSTALL_FRAMES, 6);
        for i in 0..INSTALL_FRAMES {
            check("install frame", install_frame(i), 16);
        }
        assert_eq!(install_frame(INSTALL_FRAMES), install_frame(0), "it wraps");
        // the strip fills as the frames go: no frame repeats until the last two
        assert_ne!(install_frame(0), install_frame(1));
        assert_ne!(install_frame(3), install_frame(4));
        for (name, art) in [
            ("paused", update_paused()),
            ("failed", update_failed()),
            ("done", update_done()),
        ] {
            check(name, art, 16);
        }
        // each still is its own picture
        assert_ne!(update_paused(), update_failed());
        assert_ne!(update_failed(), update_done());
        assert_ne!(update_done(), small("update"));
    }

    fn check(id: &str, icon: &[&str], size: usize) {
        assert_eq!(icon.len(), size, "{id}: rows");
        for row in icon {
            assert_eq!(row.chars().count(), size, "{id}: {row}");
            assert!(
                row.chars().all(|c| c == '.' || colour(c).is_some()),
                "{id}: {row}"
            );
        }
        let painted = icon
            .iter()
            .flat_map(|row| row.chars())
            .filter(|c| *c != '.')
            .count();
        assert!(painted > size * 4, "{id} is nearly empty");
    }

    #[test]
    fn desktop_icons_are_32_square_and_use_palette_colours() {
        for id in IDS {
            check(id, art(id), 32);
        }
    }

    #[test]
    fn small_icons_are_16_square_and_use_palette_colours() {
        for id in IDS.iter().chain(["lanlord", "update"].iter()) {
            check(id, small(id), 16);
        }
    }

    #[test]
    fn unknown_ids_fall_back_to_the_hosts_icon() {
        assert_eq!(art("nothing"), art("hosts"));
        assert_eq!(small("nothing"), small("hosts"));
    }

    #[test]
    fn the_palette_is_the_sixteen_windows_colours() {
        let letters = "kwgdnbctGlyomrpf";
        let mut seen: Vec<Color32> = letters.chars().filter_map(colour).collect();
        assert_eq!(seen.len(), 16);
        seen.sort_by_key(|c| (c.r(), c.g(), c.b()));
        seen.dedup();
        assert_eq!(seen.len(), 16, "every letter is a different colour");
        assert!(colour('x').is_none() && colour('.').is_none());
    }
}
